local GardenSieveMaker = {}
local PRODUCTS = {
    iron_gardensieve = { name = "Železni vrtno sito", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni vrtno sito za vrtove." },
    bronze_gardensieve = { name = "Bronast vrtno sito", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast vrtno sito za vrtove." },
    silver_gardensieve = { name = "Srebrn vrtno sito", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn vrtno sito za vrtove." },
    gilded_gardensieve = { name = "Pozlačen vrtno sito", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen vrtno sito za vrtove." },
    jewel_set_gardensieve = { name = "Draguljast vrtno sito", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast vrtno sito za vrtove." },
    royal_sovereign_gardensieve = { name = "Kraljevski suveren vrtno sito", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren vrtno sito z biseri za krono." },
}
local BUILDINGS = {
    gardensieve_workshop = { name = "Gardensieve delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    gardensieve_house = { name = "Gardensieve hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_gardensieve_atelier = { name = "Mojstrski gardensieve atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_gardensieve_palace = { name = "Suverena gardensieve palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GardenSieveMaker.ironStock = 12; GardenSieveMaker.bronzeStock = 10; GardenSieveMaker.woodStock = 16; GardenSieveMaker.leatherStock = 10; GardenSieveMaker.silverStock = 8; GardenSieveMaker.goldStock = 6; GardenSieveMaker.jewelStock = 4; GardenSieveMaker.pearlStock = 4
GardenSieveMaker.productStock = {}; GardenSieveMaker.buildings = {}; GardenSieveMaker.maker = nil; GardenSieveMaker.activeMaking = {}; GardenSieveMaker.totalProducts = 0; GardenSieveMaker.dayTimer = 0
function GardenSieveMaker.init() GardenSieveMaker.ironStock=12; GardenSieveMaker.bronzeStock=10; GardenSieveMaker.woodStock=16; GardenSieveMaker.leatherStock=10; GardenSieveMaker.silverStock=8; GardenSieveMaker.goldStock=6; GardenSieveMaker.jewelStock=4; GardenSieveMaker.pearlStock=4; GardenSieveMaker.productStock={}; GardenSieveMaker.buildings={}; GardenSieveMaker.maker=nil; GardenSieveMaker.activeMaking={}; GardenSieveMaker.totalProducts=0; GardenSieveMaker.dayTimer=0; print("[GardenSieveMaker] Royal Garden Sieve Maker System initialized (6 products, 4 buildings)") end
function GardenSieveMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GardenSieveMaker.maker={name=n or ("Sitar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sitar najet: %s (spretnost: %d)",GardenSieveMaker.maker.name,s),"success") end; return true end
function GardenSieveMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GardenSieveMaker.build(id) local ok,e=GardenSieveMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GardenSieveMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GardenSieveMaker.getQualityBonus() local b=0; for _,bd in ipairs(GardenSieveMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GardenSieveMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GardenSieveMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GardenSieveMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GardenSieveMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GardenSieveMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GardenSieveMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GardenSieveMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GardenSieveMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GardenSieveMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GardenSieveMaker.buildings==0 then return false,"Potrebna sitna delavnica" end; if not GardenSieveMaker.maker then return false,"Potreben sitar" end; return true end
function GardenSieveMaker.make(pt,qty) qty=qty or 1; local ok,e=GardenSieveMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GardenSieveMaker.ironStock=GardenSieveMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GardenSieveMaker.bronzeStock=GardenSieveMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GardenSieveMaker.woodStock=GardenSieveMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GardenSieveMaker.leatherStock=GardenSieveMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GardenSieveMaker.silverStock=GardenSieveMaker.silverStock-d.silverCost*qty end; if d.goldCost then GardenSieveMaker.goldStock=GardenSieveMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GardenSieveMaker.jewelStock=GardenSieveMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GardenSieveMaker.pearlStock=GardenSieveMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GardenSieveMaker.maker then t=math.max(1,t-math.floor(GardenSieveMaker.maker.skill/13)) end; table.insert(GardenSieveMaker.activeMaking,{id="gardensieve_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GardenSieveMaker.completeMaking(m) local q=1.0+(GardenSieveMaker.getQualityBonus()/100); if GardenSieveMaker.maker then q=q+(GardenSieveMaker.maker.skill/140) end; q=math.min(2.5,q); GardenSieveMaker.productStock[m.productType]=(GardenSieveMaker.productStock[m.productType] or 0)+m.quantity; GardenSieveMaker.totalProducts=GardenSieveMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GardenSieveMaker.maker then GardenSieveMaker.maker.itemsMade=GardenSieveMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GardenSieveMaker.maker.skill=math.min(100,GardenSieveMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sito izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gardensieve.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GardenSieveMaker.update(dt) if not _G.state then return end; GardenSieveMaker.dayTimer=GardenSieveMaker.dayTimer+dt; if GardenSieveMaker.dayTimer>=30 then GardenSieveMaker.dayTimer=0; for i=#GardenSieveMaker.activeMaking,1,-1 do local m=GardenSieveMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GardenSieveMaker.completeMaking(m); table.remove(GardenSieveMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GardenSieveMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GardenSieveMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GardenSieveMaker.getStats() return {ironStock=GardenSieveMaker.ironStock,bronzeStock=GardenSieveMaker.bronzeStock,woodStock=GardenSieveMaker.woodStock,leatherStock=GardenSieveMaker.leatherStock,silverStock=GardenSieveMaker.silverStock,goldStock=GardenSieveMaker.goldStock,jewelStock=GardenSieveMaker.jewelStock,pearlStock=GardenSieveMaker.pearlStock,productStock=GardenSieveMaker.productStock,numBuildings=#GardenSieveMaker.buildings,hasMaker=GardenSieveMaker.maker~=nil,makerName=GardenSieveMaker.maker and GardenSieveMaker.maker.name or "—",makerSkill=GardenSieveMaker.maker and GardenSieveMaker.maker.skill or 0,activeMaking=#GardenSieveMaker.activeMaking,totalProducts=GardenSieveMaker.totalProducts} end
return GardenSieveMaker
